targets.expr:
kube_pod_container_resource_requests{
  cluster="$cluster",
  job="kube-state-metrics",
  resource="cpu",
  pod=~"^$service-$env-.*$",
  container!=""
}
* on(pod, namespace) group_left(label_rems_application_group,  label_rems_service)
kube_pod_labels{cluster="$cluster"}

kube_pod_container_resource_limits{
  cluster="$cluster",
  job="kube-state-metrics",
  resource="cpu",
  pod=~"^$name.*$",
  container!=""
}
* on(pod, namespace) group_left(label_application_group, label_app_kubernetes_io_name)
kube_pod_labels{cluster="$cluster"}

container_memory_working_set_bytes{
  cluster="$cluster",
  job="kubelet",
  pod=~"^$service-$env-.*$"
}
* on(pod, namespace) group_left(label_application_group, label_app_kubernetes_io_name)
kube_pod_labels{cluster="$cluster", }

kube_pod_container_resource_requests{
  cluster="$cluster",
  job="kube-state-metrics",
  resource="memory",
  pod=~"^$service-$env-.*$"
}
* on(pod, namespace) group_left(label_rems_application_group,  label_rems_service)
kube_pod_labels{cluster="$cluster"}

kube_pod_container_resource_limits{
  cluster="$cluster",
  job="kube-state-metrics",
  resource="memory",
  pod=~"^$service-$env-.*$"
}
* on(pod, namespace) group_left(label_rems_application_group, label_rems_service)
kube_pod_labels{cluster="$cluster"}

sum by(pod) (
  increase(container_cpu_cfs_throttled_periods_total{
    job="kubelet", metrics_path="/metrics/cadvisor",
    pod=~"^$service-$env-.*$", container!=""
  }[$__rate_interval])
) / sum by(pod) (
  increase(container_cpu_cfs_periods_total{
    job="kubelet", metrics_path="/metrics/cadvisor",
    pod=~"^$service-$env-.*$", container!=""
  }[$__rate_interval])
)

increase(
  kube_pod_container_status_restarts_total{
    cluster="$cluster", pod=~"^$service-$env-.*$"
  }[1h]
)
* on(pod) group_left(rems_environment)
kube_pod_labels{rems_environment="$env"}

count(
  kube_pod_status_phase{cluster="$cluster", phase="Running", pod=~"^$service-$env-.*$"}
  * on(pod) group_left(rems_environment)
  kube_pod_labels{rems_environment="$env"}
)
